entries[233272] = { ["name"] = "Zerschmetternder Stern", ["text"] = "200 Meter Reichweite\nSofort\nGoroth wählt ein Ziel, schleudert nach 6 Sek. ' Zerschmetternder Stern ' an dessen Position und fügt so allen Gegnern innerhalb von 200 Metern 53420 Feuerschaden zu. Dieser Schaden wird für jeden Höllenstachel, mit dem ' Zerschmetternder Stern ' in Berührung kommt, verringert.\n\nWenn ' Zerschmetternder Stern ' nicht mit Höllenstacheln in Berührung kommt, wird das Ziel entzündet und erleidet 12 Sek. lang alle 1 Sek. 63219 Feuerschaden.\n\nAlle anderen Gegner, die von ' Zerschmetternder Stern ' auf dem Weg zum Ziel getroffen werden, erleiden 16081 Feuerschaden." }
