entries[234013] = { ["name"] = "Berührung von Sargeras", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer gefallene Avatar verflucht 3 Ziele, wodurch nach 10 Sek. Schattenenergie aus ihnen hervorbricht und eine Heilungsabsorption in Höhe von 1455 gleichmäßig auf alle getroffenen Spielercharaktere innerhalb von 6 Metern aufgeteilt wird.\n\nZusätzlich erleiden alle getroffenen Spielercharaktere 227 Schattenschaden." }
